create function public.manage_profile(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();pr public.teacher_profiles;rid uuid;begin perform private.require_access(s,true);if p->>'action'='create' then if private.role()<>'administrator'or not exists(select 1 from public.memberships where id=(p->>'teacherId')::uuid and school_id=s and role='teacher'and active)then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.teacher_profiles(school_id,teacher_id,display_name,designation,subjects,classes)values(s,(p->>'teacherId')::uuid,p->>'displayName',coalesce(p->>'designation',''),array(select jsonb_array_elements_text(p->'subjects')),array(select jsonb_array_elements_text(p->'classes')))returning id into rid;else select * into pr from public.teacher_profiles where id=(p->>'profileId')::uuid and school_id=s for update;if not found then raise exception 'FORBIDDEN'using errcode='42501';end if;
if p->>'action'='draft' then if private.role()<>'teacher'or pr.teacher_id<>auth.uid()then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.profile_revisions(school_id,profile_id,author_id,content,state)values(s,pr.id,auth.uid(),p->'content','submitted')returning id into rid;
elsif private.role()='administrator' then if p->>'action'='approve' then if p->>'audience'='public'and not exists(select 1 from public.schools where id=s and public_enabled)then raise exception 'PUBLIC_NOT_ENABLED';end if;update public.teacher_profiles set approved_fields=(select content from public.profile_revisions where id=(p->>'revisionId')::uuid and profile_id=pr.id and state='submitted'),visible=true,audience=p->>'audience',published_at=now(),revision=revision+1 where id=pr.id;update public.profile_revisions set state='approved'where id=(p->>'revisionId')::uuid and profile_id=pr.id;elsif p->>'action'='unpublish' then update public.teacher_profiles set visible=false,revision=revision+1 where id=pr.id;else raise exception 'INVALID_ACTION';end if;rid:=pr.id;else raise exception 'FORBIDDEN'using errcode='42501';end if;end if;perform private.audit(s,'profile.changed',rid,p->>'reason');return rid;end$$;
create function public.professional_update(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare pr public.teacher_profiles;i uuid;begin select * into pr from public.teacher_profiles where id=(p->>'profileId')::uuid;perform private.require_access(pr.school_id,true);if private.role()='teacher'and pr.teacher_id=auth.uid()and p->>'action'='submit' then insert into public.professional_updates(school_id,profile_id,title,kind,date,evidence_reference)values(pr.school_id,pr.id,p->>'title',p->>'kind',(p->>'date')::date,p->>'evidenceReference')returning id into i;elsif private.role()='administrator'and p->>'action'='approve' then update public.professional_updates set approved=true where id=(p->>'id')::uuid and profile_id=pr.id returning id into i;else raise exception 'FORBIDDEN'using errcode='42501';end if;perform private.audit(pr.school_id,'professional_update.changed',i);return i;end$$;
create function public.profile_detail(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare pr public.teacher_profiles;begin select * into pr from public.teacher_profiles where id=(p->>'profileId')::uuid;if not private.profile_visible(pr.id)then raise exception 'PROFILE_UNAVAILABLE'using errcode='42501';end if;return jsonb_build_object('id',pr.id,'displayName',pr.display_name,'designation',pr.designation,'subjects',pr.subjects,'classes',pr.classes,'about',pr.approved_fields,'updates',(select coalesce(jsonb_agg(jsonb_build_object('title',title,'kind',kind,'date',date)),'[]')from public.professional_updates where profile_id=pr.id and approved),'statistics',jsonb_build_object('publishedArticleCount',(select count(*)from public.teacher_articles where profile_id=pr.id and published_revision is not null and not archived and(audience='public'or private.school()=pr.school_id)),'completedWorkshopCount',(select count(*)from public.professional_updates where profile_id=pr.id and approved and kind='workshop'and date<=current_date),'period','all time','refreshedAt',now()));end$$;
create function public.set_public_policy(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin perform private.require_access(s);if private.role()<>'administrator'or length(coalesce(p->>'reason',''))=0 then raise exception 'FORBIDDEN'using errcode='42501';end if;update public.schools set public_enabled=(p->>'enabled')::boolean,indexing_enabled=coalesce((p->>'indexingEnabled')::boolean,false)where id=s;perform private.audit(s,'school.public_policy',s,p->>'reason');end$$;
create function public.correct_insight(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare u uuid:=(p->>'studentId')::uuid;begin if not private.student_access(u)then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into private.insight_revisions(student_id,source_version,snapshot)select student_id,source_version,to_jsonb(i)from public.student_insights i where student_id=u;update public.student_insights set correction=p->>'correction',suppressed=(p->>'suppressed')::boolean,content=null,status='corrected',updated_at=now()where student_id=u;perform private.audit(private.school(),'insight.corrected',u,p->>'reason');end$$;
create function public.learning_statistics(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=coalesce((p->>'studentId')::uuid,auth.uid());r record;unit jsonb;answered int:=0;correct int:=0;unanswered int:=0;eligible int;finalized int;ontime int;v int;topics jsonb;begin perform private.learning_access();if u<>auth.uid()and not private.student_access(u)then raise exception 'FORBIDDEN'using errcode='42501';end if;
for r in select q.content,k.key,a.response from public.results rr join public.exam_questions q on q.version_id=rr.version_id join private.question_keys k on k.version_id=q.version_id and k.question_id=q.id left join public.answers a on a.attempt_id=rr.attempt_id and a.question_id=q.id join public.exam_versions e on e.id=rr.version_id where rr.student_id=u and rr.school_id=private.school()and private.report_result(rr.version_id,u)and(p->>'subject'is null or e.subject=p->>'subject')and(p->>'from'is null or rr.published_at>=(p->>'from')::timestamptz)and(p->>'to'is null or rr.published_at<(p->>'to')::timestamptz)loop
if r.content->>'type'='subjective'then continue;end if;if r.content->>'type'in('mcq','boolean')then if r.response is null or r.response='null'::jsonb then unanswered:=unanswered+1;else answered:=answered+1;if private.objective_score(r.content,r.key,r.response)>0 then correct:=correct+1;end if;end if;else for unit in select value from jsonb_array_elements(r.key->'units')loop if coalesce(r.response->>(unit->>'id'),'')=''then unanswered:=unanswered+1;else answered:=answered+1;v:=private.objective_score(r.content,jsonb_build_object('units',jsonb_build_array(unit)),r.response);if v>0 then correct:=correct+1;end if;end if;end loop;end if;end loop;
select count(*),count(a.finalized_at),count(*)filter(where a.finalized_at<=a.deadline)into eligible,finalized,ontime from public.exam_recipients rec join public.exam_versions e on e.id=rec.version_id left join public.attempts a on a.version_id=rec.version_id and a.student_id=u where rec.student_id=u and rec.school_id=private.school()and not rec.exempt and e.status<>'cancelled'and rec.closes_at<=now()and private.report_result(e.id,u)and(p->>'subject'is null or e.subject=p->>'subject');
select coalesce(jsonb_agg(t),'[]')into topics from(select coalesce(q.content->>'primaryTopic','Unclassified')as topic,sum((published_score->>'score')::int)as earned,sum((published_score->>'maximum')::int)as maximum,count(*)as scored_units,count(distinct rr.version_id)as assessments,case when count(*)>=3 and count(distinct rr.version_id)>=2 then 'recurring-evidence'else 'more-evidence-needed'end as sufficiency from public.results rr join public.exam_questions q on q.version_id=rr.version_id cross join lateral jsonb_array_elements(rr.scores)published_score join public.exam_versions e on e.id=rr.version_id where published_score->>'questionId'=q.id::text and rr.student_id=u and rr.school_id=private.school()and private.report_result(rr.version_id,u)and(p->>'subject'is null or e.subject=p->>'subject')and(p->>'from'is null or rr.published_at>=(p->>'from')::timestamptz)and(p->>'to'is null or rr.published_at<(p->>'to')::timestamptz)group by coalesce(q.content->>'primaryTopic','Unclassified'))t;
return jsonb_build_object('answeredObjectiveUnits',answered,'correctObjectiveUnits',correct,'unansweredObjectiveUnits',unanswered,'objectiveAccuracy',correct::numeric/nullif(answered,0),'eligibleClosedAssignments',eligible,'finalizedAttempts',finalized,'completionRate',finalized::numeric/nullif(eligible,0),'onTimeFinalizations',ontime,'topics',topics,'generatedAt',now());end$$;
create function public.request_export(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();u uuid:=(p->>'studentId')::uuid;i uuid;begin if private.role()not in('teacher','administrator')or not private.student_access(u)then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.report_exports(school_id,actor_id,filters,source_version)values(s,auth.uid(),p,coalesce((select sum(revision)from public.results where student_id=u),0))returning id into i;insert into public.outbox(school_id,kind,dedup_key,payload)values(s,'export','export:'||i,jsonb_build_object('exportId',i));perform private.audit(s,'report.export',u);return i;end$$;
create function public.runtime_export_data(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e public.report_exports;old text;data jsonb;begin select * into e from public.report_exports where id=(p->>'id')::uuid and expires_at>now();if not found then return null;end if;old:=current_setting('request.jwt.claim.sub',true);perform set_config('request.jwt.claim.sub',e.actor_id::text,true);data:=public.student_progress(e.filters);perform set_config('request.jwt.claim.sub',coalesce(old,''),true);return jsonb_build_object('exportId',e.id,'schoolId',e.school_id,'filters',e.filters,'data',data);end$$;
create function public.runtime_export_finish(p jsonb)returns void language sql security definer set search_path='' as $$update public.report_exports set object_key=p->>'objectKey',status='ready'where id=(p->>'id')::uuid and expires_at>now()$$;
create function public.export_download(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare e public.report_exports;begin select * into e from public.report_exports where id=(p->>'id')::uuid and actor_id=auth.uid()and school_id=private.school()and expires_at>now()and status='ready';if not found or not private.student_access((e.filters->>'studentId')::uuid)or e.source_version<>coalesce((select sum(revision)from public.results where student_id=(e.filters->>'studentId')::uuid),0)then raise exception 'EXPORT_UNAVAILABLE'using errcode='42501';end if;return jsonb_build_object('objectKey',e.object_key);end$$;
revoke execute on function public.manage_profile(jsonb),public.professional_update(jsonb),public.profile_detail(jsonb),public.set_public_policy(jsonb),public.correct_insight(jsonb),public.learning_statistics(jsonb),public.request_export(jsonb),public.export_download(jsonb),public.runtime_export_data(jsonb),public.runtime_export_finish(jsonb)from public,anon,authenticated;
grant execute on function public.manage_profile(jsonb),public.professional_update(jsonb),public.profile_detail(jsonb),public.set_public_policy(jsonb),public.correct_insight(jsonb),public.learning_statistics(jsonb),public.request_export(jsonb),public.export_download(jsonb)to authenticated;grant execute on function public.profile_detail(jsonb)to anon;grant execute on function public.runtime_export_data(jsonb),public.runtime_export_finish(jsonb)to service_role;
